// src/pages/LoginPage.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function LoginPage() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError(null);

    if (!username.trim() || !password) {
      setError("Введіть логін і пароль.");
      return;
    }

    setLoading(true);

    try {
      // Очистимо старі токени перед запитом (щоб уникнути конфліктів)
      localStorage.removeItem("token");
      localStorage.removeItem("refresh");

      const res = await fetch("http://127.0.0.1:8000/api/token/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: username.trim(), password }),
      });

      // Якщо backend повертає HTML (500 сторінка) — ловимо це
      const text = await res.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch (err) {
        // не JSON — помилка сервера
        throw new Error("Сервер повернув некоректну відповідь: " + text.slice(0, 200));
      }

      if (!res.ok) {
        // Відображаємо повідомлення з backend (якщо є)
        const msg = data.detail || JSON.stringify(data);
        throw new Error(msg);
      }

      // Успішно — зберігаємо токени
      if (data.access) {
        localStorage.setItem("token", data.access);
      }
      if (data.refresh) {
        localStorage.setItem("refresh", data.refresh);
      }

      // Опціонально: можна зберегти username для UI
      localStorage.setItem("username", username.trim());

      // Перенаправляємо на головну
      navigate("/");

    } catch (err) {
      // показуємо користувачу дружнє повідомлення
      console.error("Login error:", err);
      setError(typeof err === "string" ? err : err.message || "Помилка при вході");
      // Видаляємо потенційно пошкоджені токени
      localStorage.removeItem("token");
      localStorage.removeItem("refresh");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-container" style={{ maxWidth: 420, margin: "40px auto", padding: 20 }}>
      <h2>Вхід</h2>

      {error && (
        <div style={{ background: "#fdecea", color: "#c62828", padding: 10, borderRadius: 8, marginBottom: 12 }}>
          {error}
        </div>
      )}

      <form onSubmit={handleLogin} style={{ display: "grid", gap: 10 }}>
        <input
          type="text"
          placeholder="Логін"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
          required
          autoComplete="username"
        />
        <input
          type="password"
          placeholder="Пароль"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
          autoComplete="current-password"
        />

        <button type="submit" disabled={loading}>
          {loading ? "Увійти..." : "Увійти"}
        </button>
      </form>
    </div>
  );
}

export default LoginPage;
